/// A link's name for people and screen readers: the brand's own name ("Instagram"), "الموقع" / "Website", or the
/// member's label for Other ("تاني" / "Other" when it has none).
String linkPlatformName(AppLocalizations l10n, LinkPlatform platform, {String? label}) => switch (platform) {
      LinkPlatform.website => l10n.profileWebsite,
      LinkPlatform.other => (label?.trim().isNotEmpty ?? false) ? label!.trim() : l10n.profileLinkOther,
      _ => platform.brandName!,
    };

/// A platform's icon (SPEC F14): the brand marks come from one bundled set, Simple Icons (CC0, simpleicons.org;
/// LinkedIn from its 10.4.0 release, the last one that has it), drawn from their 24 × 24 path in [color]. Website and
/// Other use the app's globe and link icons. Brand marks never mirror in RTL. The icon itself is decorative: the
/// control it sits in carries the name.
class PlatformIcon extends StatelessWidget {
  const PlatformIcon(this.platform, {super.key, this.size = 22, this.color});

  final LinkPlatform platform;
  final double size;

  /// Defaults to the [IconTheme] color.
  final Color? color;

  static final _parsed = <LinkPlatform, Path>{};

  static Path? pathOf(LinkPlatform platform) {
    final data = _paths[platform];
    if (data == null) return null;
    return _parsed[platform] ??= parseSvgPath(data);
  }

  @override
  Widget build(BuildContext context) {
    final color = this.color ?? IconTheme.of(context).color ?? DefaultTextStyle.of(context).style.color ?? Colors.black;
    final path = pathOf(platform);
    if (path == null) {
      return Icon(platform == LinkPlatform.website ? Icons.language_rounded : Icons.link_rounded, size: size, color: color);
    }
    return ExcludeSemantics(
      child: SizedBox.square(dimension: size, child: CustomPaint(painter: _BrandPainter(path, color))),
    );
  }

