class _BrandPainter extends CustomPainter {
  _BrandPainter(this.path, this.color);

  final Path path;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    canvas
      ..save()
      ..scale(size.width / 24, size.height / 24)
      ..drawPath(path, Paint()..color = color..isAntiAlias = true)
      ..restore();
  }

  @override
  bool shouldRepaint(_BrandPainter old) => old.path != path || old.color != color;
}
